using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class EconomyDetailView:MonoBehaviour {
  GameRuntime game;string kind;int index;float next;Text facts;public void Initialize(GameRuntime runtime,string selected,int i){game=runtime;kind=selected;index=i;WorkshopUIFactory.Button("CloseEconomyDetail",transform,"Back",()=>game.UserShow(kind));facts=WorkshopUIFactory.Label("EconomyDetailFacts",transform,"",15,54);facts.GetComponent<LayoutElement>().preferredHeight=-1;facts.alignment=TextAnchor.UpperLeft;Refresh();}
  void Update(){if(Time.unscaledTime<next)return;next=Time.unscaledTime+.25f;Refresh();}
  void Refresh(){var s=game.State;string T(string key)=>SettingsRules.Text(s.Settings.language,key);string N(ScientificNumber n)=>NumberFormatting.Format(n,s.Settings.numberFormat,s.Settings.language);if(kind=="training"){string track=PrestigeAutomation.Tracks[index];var baseline=ScientificNumber.From(track=="integration"?PrestigeRules.V("trainingGBase"):Balance.TrainingCreditBase).Multiply(ScientificNumber.From(track=="integration"?PrestigeRules.V("trainingGGrowth"):Balance.TrainingCreditGrowth).Pow(Game.TrainingLevel(s,track)));var cost=Game.TrainingCost(s,track);bool intro=track=="quality"&&Game.IntroQuality(s);var candidate=s.Copy();candidate.Training=new Job{id=track,intro=intro,modelTransferEligible=Game.Level(s,"modelTransfer")>0&&s.Industry.trainingStarted<IndustryBalance.TransferStarts};double speed=intro?1:Game.WorkSpeed(candidate);facts.text=(track=="integration"?"Integration":T("workshop:"+track))+" · Lv. "+Game.TrainingLevel(s,track)+"\nBase: "+N(baseline)+" Credits\nStart: "+N(cost)+" Credits + "+N(Game.TrainingData(s,track))+" Data\nPrice saving: "+(baseline.IsZero?0:Math.Max(0,1-cost.Divide(baseline).ToDouble())*100).ToString("F2",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" %\nWork: "+Game.TrainingWork(s,track).ToString("F2",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" s\nStart duration: "+(Game.TrainingWork(s,track)/speed).ToString("F2",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" s\nCurrent work rate: ×"+speed.ToString("F4",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+"\n"+(intro?"Introductory lesson: free, fixed 20 s.":"Elapsed time drives progress; current bonuses can change the remaining duration.")+"\n"+(Game.TrainingAvailable(s,track)?"Available":"Unavailable");}else{var d=Balance.Research[index];var jobs=PrestigeAutomation.ResearchJobs(s).ToArray();var running=jobs.FirstOrDefault(j=>j.id==d.Id);var cost=Game.ResearchCost(s,index);bool intro=d.Id=="dataGeneration"&&Game.IntroResearch(s);facts.text=T("research:"+d.Id)+" · Lv. "+s.Research[index]+"\n"+ResearchCopy.Describe(s,d.Id)+"\nStart: "+N(cost)+" Data\nMissing: "+N(cost.Subtract(s.Data))+" Data\nWork: "+Game.ResearchWork(s,index).ToString("F2",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" s\nCurrent work rate: ×"+(intro?1:Game.ResearchSpeed(s)).ToString("F4",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+"\n"+string.Join("\n",d.Requires.Select(r=>T("research:"+r.Id)+" · "+Game.Level(s,r.Id)+" / "+r.Level))+"\n"+(Game.ResearchBlock(s,index)??"Available")+(running==null?"":"\nRemaining: "+Game.ResearchRemainingSeconds(s,running).ToString("F2",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" s · "+"Paid at start");if(ItemSystemV3.Enabled(s)&&!intro)facts.text+="\n"+ItemV3ResearchDetails.StoredStart(s,running);}}
 }
}
